const TOKEN_LIFETIME_MS = 15 * 60 * 1000;

export interface ResetToken {
  expiresAt: string;
}

export function resetToken(now: number | Date): ResetToken {
  const issuedAt = now instanceof Date ? now.getTime() : now;

  return {
    expiresAt: new Date(issuedAt + TOKEN_LIFETIME_MS).toISOString(),
  };
}
EOF
