export const READY = 'Choose a new password';
export const RECOVER = 'Request a new reset link';

// A link is usable only while now is strictly earlier than expiresAt.
// Expiry at the exact instant, or any unparseable timestamp, offers recovery.
export function resetState(expiresAt: unknown, now: number | Date): string {
  const expiry = typeof expiresAt === 'string' ? Date.parse(expiresAt) : NaN;
  const current = now instanceof Date ? now.getTime() : now;
  if (!Number.isFinite(expiry) || typeof current !== 'number' || !Number.isFinite(current)) {
    return RECOVER;
  }
  return current < expiry ? READY : RECOVER;
}
EOF
